  ///メソッド：ログアウト
  Future<void> signOut(dynamic chatListChannel) async {
    await FirebaseSerivce().firebaseSignOut();
    chatListChannel.closefriendList();
    userData = ProfileData();
    notifyListeners();
  }

  ///メソッド：ユーザ資料更新する
  Future<void> updateProfile(String uid, UpdateUser updateData) async {
    userData = await UserService().requestGetUserData(uid);
    notifyListeners();
  }

  ///メソッド： 読んでいない通知数取得する
  Future<void> getNotificationCount() async {
    notReadNotificationCount = await NotificationService().requestNoReadNotificationAmount(userUId: userData.uid);
    notifyListeners();
  }

  ///メソッド： 通知数更新する
  void updateNotificationCount({bool allRead = false}) {
    if (allRead) {
      notReadNotificationCount = "0";
    } else {
      int count = int.parse(notReadNotificationCount);
      count--;
      notReadNotificationCount = "$count";
    }

    notifyListeners();
  }
}
